def solve(coins, amount):
    # Edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Filter out non-positive coin values, as they don't help
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    # DP array
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= i:
                cand = dp[i - c] + 1
                if cand < best:
                    best = cand
        dp[i] = best
    return dp[amount] if dp[amount] != INF else -1

